import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Analytics = ({ token }) => {
  const [stats, setStats] = useState({
    totalEntries: 0,
    totalAmount: 0,
    anomalies: 0,
    categories: {},
    recentEntries: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const fetchAnalytics = async () => {
    try {
      // Fetch all entries for analytics (use high per_page to get all)
      const response = await axios.get('http://localhost:5000/api/ledger-entries?page=1&per_page=1000', {
        headers: { Authorization: `Bearer ${token}` }
      });

      const entries = response.data.entries || [];
      const totalEntries = entries.length;
      const totalAmount = entries.reduce((sum, entry) => sum + entry.amount, 0);
      const anomalies = entries.filter(entry => entry.is_anomaly).length;

      // Category breakdown
      const categories = {};
      entries.forEach(entry => {
        categories[entry.category] = (categories[entry.category] || 0) + entry.amount;
      });

      setStats({
        totalEntries,
        totalAmount,
        anomalies,
        categories,
        recentEntries: entries.slice(0, 5)
      });
      setLoading(false);
    } catch (error) {
      console.error('Error fetching analytics:', error);
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR'
    }).format(amount);
  };

  if (loading) {
    return (
      <div className="analytics-container">
        <div className="loading">Loading analytics...</div>
      </div>
    );
  }

  return (
    <div className="analytics-container">
      <div className="analytics-header">
        <h1>Analytics Dashboard</h1>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <h3>Total Entries</h3>
          <div className="stat-number">{stats.totalEntries}</div>
        </div>

        <div className="stat-card">
          <h3>Total Amount</h3>
          <div className="stat-number">{formatCurrency(stats.totalAmount)}</div>
        </div>

        <div className="stat-card anomaly">
          <h3>Anomalies Detected</h3>
          <div className="stat-number">{stats.anomalies}</div>
        </div>

        <div className="stat-card">
          <h3>Anomaly Rate</h3>
          <div className="stat-number">
            {stats.totalEntries > 0 ? ((stats.anomalies / stats.totalEntries) * 100).toFixed(1) : 0}%
          </div>
        </div>
      </div>

      <div className="analytics-grid">
        <div className="card">
          <h2>📊 Category Breakdown</h2>
          <div className="category-breakdown">
            {Object.entries(stats.categories).map(([category, amount]) => {
              const percentage = stats.totalAmount > 0 ? ((amount / stats.totalAmount) * 100).toFixed(1) : 0;
              return (
                <div key={category} className="category-row">
                  <div className="category-info">
                    <div className="category-header">
                      <span className="category-name">{category}</span>
                      <span className="category-percentage">{percentage}%</span>
                    </div>
                    <div className="category-bar">
                      <div 
                        className="category-fill" 
                        style={{ width: `${percentage}%` }}
                      ></div>
                    </div>
                  </div>
                  <div className="category-amount">{formatCurrency(amount)}</div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="card">
          <h2>🕒 Recent Transactions</h2>
          <div className="recent-transactions">
            {stats.recentEntries.map(entry => (
              <div key={entry.id} className={`transaction-card ${entry.is_anomaly ? 'anomaly' : ''}`}>
                <div className="transaction-header">
                  <div className="transaction-desc">{entry.description}</div>
                  <div className="transaction-date">{new Date(entry.date).toLocaleDateString('en-IN')}</div>
                </div>
                <div className="transaction-footer">
                  <div className="transaction-amount">{formatCurrency(entry.amount)}</div>
                  <div className="transaction-meta">
                    <span className="category-tag">{entry.category}</span>
                    {entry.is_anomaly && <span className="anomaly-indicator">⚠️ Anomaly</span>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
